arguments.argument:
/*미니맵*/

part_x1 = view_xview*xscale
part_y1 = view_yview*yscale
part_x2 = (view_xview+view_wview)*xscale
part_y2 = (view_yview+view_hview)*yscale

x_loc = view_xview+x_loc2
y_loc = view_yview+y_loc2

x=x_loc
y=y_loc

draw_set_color(c_silver)
draw_rectangle(x_loc-0.5, y_loc-0.5, x_loc+0.5 + width, y_loc+0.5 + height, 0)

draw_set_blend_mode(bm_subtract)
draw_surface(min_surf, x_loc, y_loc)
draw_set_blend_mode(bm_normal)

if sys_mouse.vab_unit=1
{
    with(sys_mouse.vab_unit_id[0])
    {
        if cre_go_x>0 and cre_go_y>0
        {
            draw_set_alpha(0.3)
            draw_set_color(c_green)
            draw_line_width(x*other.xscale+other.x_loc, y*other.yscale+other.y_loc, cre_go_x*other.xscale+other.x_loc, cre_go_y*other.yscale+other.y_loc, 4*other.mscale)
            draw_circle(cre_go_x*other.xscale+other.x_loc, cre_go_y*other.yscale+other.y_loc, 5*other.mscale, 0)
            draw_set_color(c_black)
            draw_set_alpha(1)
        }
    }
}

with(obj_moni)
{
    if !sk_in_fog(x, y, 1)
    {
        draw_set_color(c_green)
        draw_circle(x*other.xscale+other.x_loc, y*other.yscale+other.y_loc, other.mscale*5, 0)
    }
}

with(obj_unit)
{
    if sk_in_fog(x, y, 0) or (sk_in_fog(x, y, 2) and drag_ok=0)
    {
        sk_udraw_color(player)
        if drag_ok!=0{draw_circle(x*other.xscale+other.x_loc, y*other.yscale+other.y_loc, other.mscale*5, 0)}
        else
        {
            draw_set_alpha(0.5)
            draw_circle(x*other.xscale+other.x_loc, y*other.yscale+other.y_loc, other.mscale*8, 0)
            draw_set_alpha(1)
        }
    }
}

with(obj_bil)
{
    if !sk_in_fog(x, y, 1)
    {
        sk_udraw_color(player)
        if drag_ok!=0{draw_circle(x*other.xscale+other.x_loc, y*other.yscale+other.y_loc, other.mscale*5, 0)}
        else
        {
            draw_set_alpha(0.5)
            draw_circle(x*other.xscale+other.x_loc, y*other.yscale+other.y_loc, other.mscale*8, 0)
            draw_set_alpha(1)
        }
    }
}

draw_set_color(c_orange)
draw_rectangle(x_loc-0.5, y_loc-0.5, x_loc+0.5 + width, y_loc+0.5 + height, true)

draw_set_color(c_orange)
draw_rectangle(x_loc + part_x1, y_loc + part_y1, x_loc + part_x2,  y_loc + part_y2, true)

draw_set_color(c_black)
